<div class="section-heading"><div><div class="eyebrow"><?=htmlspecialchars($ticket['protocol'])?></div><h1><?=htmlspecialchars($ticket['subject'])?></h1><p class="text-secondary mb-0"><?=$platform?htmlspecialchars($ticket['tenant_name']??''):''?> · <?=htmlspecialchars(['open'=>'Aberto','in_progress'=>'Em atendimento','waiting_user'=>'Aguardando cliente','resolved'=>'Resolvido','closed'=>'Fechado'][$ticket['status']]??$ticket['status'])?></p></div><a class="btn btn-light" href="<?=$platform?'/master/support':'/support'?>">Voltar</a></div>
<div class="row g-4"><div class="col-lg-8"><div class="card mb-4"><div class="card-body"><strong>Descrição original</strong><p class="mt-2 mb-0" style="white-space:pre-wrap"><?=htmlspecialchars($ticket['description'])?></p></div></div><div class="card"><div class="card-header"><strong>Conversa</strong></div><div class="card-body"><?php foreach($messages as $m):?><div class="border-bottom py-3"><div class="d-flex justify-content-between"><strong><?=htmlspecialchars($m['user_name'])?></strong><small class="text-secondary"><?=htmlspecialchars($m['created_at'])?></small></div><div style="white-space:pre-wrap"><?=htmlspecialchars($m['message'])?></div><?php if(!empty($m['attachment_path'])):?><a class="btn btn-sm btn-outline-secondary mt-2" href="/support/attachments/<?=(int)$m['id']?>">Baixar anexo</a><?php endif;?></div><?php endforeach;?><?php if(!$messages):?><div class="text-secondary mb-3">Ainda não há respostas.</div><?php endif;?><form method="post" enctype="multipart/form-data" action="/support/<?=(int)$ticket['id']?>/message" class="mt-3"><?php echo \App\Core\CSRF::field();?><textarea class="form-control" name="message" rows="4" required placeholder="Escreva uma resposta"></textarea><label class="form-label mt-2">Anexo opcional (JPG, PNG, PDF ou TXT até 5 MB)</label><input class="form-control" type="file" name="attachment" accept=".jpg,.jpeg,.png,.pdf,.txt"><button class="btn btn-primary mt-2">Enviar mensagem</button></form></div></div></div>
<div class="col-lg-4"><div class="card mb-4"><div class="card-body"><div class="eyebrow">Acesso assistido</div><?php if($ticket['remote_access_allowed']):?><div class="alert alert-success">O cliente autorizou acesso temporário ao painel para este chamado.</div><?php else:?><div class="alert alert-light">Acesso remoto não autorizado.</div><?php endif;?><?php if(!$platform):?><form method="post" action="/support/<?=(int)$ticket['id']?>/remote-access"><?php echo \App\Core\CSRF::field();?><input type="hidden" name="allow" value="<?=$ticket['remote_access_allowed']?0:1?>"><button class="btn <?=$ticket['remote_access_allowed']?'btn-outline-danger':'btn-outline-primary'?> w-100"><?=$ticket['remote_access_allowed']?'Revogar autorização':'Autorizar acesso ao suporte'?></button></form><?php elseif($ticket['remote_access_allowed']&&\App\Core\Authorization::allows('master.support.impersonate')):?><form method="post" action="/support/<?=(int)$ticket['id']?>/start-access"><?php echo \App\Core\CSRF::field();?><button class="btn btn-danger w-100">Acessar conta para suporte</button></form><small class="text-secondary d-block mt-2">O acesso será registrado e exibirá um banner permanente.</small><?php endif;?></div></div>
<?php if($platform):?><div class="card mb-4"><div class="card-body"><form method="post" action="/support/<?=(int)$ticket['id']?>/status"><?php echo \App\Core\CSRF::field();?><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['open'=>'Aberto','in_progress'=>'Em atendimento','waiting_user'=>'Aguardando cliente','resolved'=>'Resolvido','closed'=>'Fechado'] as $v=>$l):?><option value="<?=$v?>" <?=$ticket['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><button class="btn btn-outline-primary w-100 mt-2">Atualizar status</button></form></div></div><?php endif;?>
<?php if($platform&&$accessSessions):?><div class="card"><div class="card-header"><strong>Acessos realizados</strong></div><div class="card-body small"><?php foreach($accessSessions as $s):?><div class="border-bottom py-2"><strong><?=htmlspecialchars($s['master_name']??'Suporte')?></strong><br><?=htmlspecialchars($s['started_at'])?><?=!empty($s['ended_at'])?' → '.htmlspecialchars($s['ended_at']):' · em andamento'?></div><?php endforeach;?></div></div><?php endif;?></div></div>
